"use strict";

/** Tiny in-memory cache. Entries expire after ttlMs. */
class KvCache {
  constructor(ttlMs) {
    this.ttlMs = ttlMs;
    this.store = new Map();
  }

  set(key, value) {
    this.store.set(key, { value, at: Date.now() });
  }

  get(key) {
    const entry = this.store.get(key);
    if (!entry) {
      return undefined;
    }
    if (Date.now() - entry.at >= this.ttlMs) {
      this.store.delete(key);
      return undefined;
    }
    return entry.value;
  }
}

module.exports = { KvCache };
